<?php

use App\Models\PilketosPasangan;
use App\Models\PilketosPeriode;
use App\Services\PilketosCandidateService;
use App\Services\PilketosPhotoUploadService;
use App\Services\PilketosStudentDirectory;
use Livewire\Attributes\Layout;
use Livewire\WithPagination;
use Livewire\Volt\Component;

new #[Layout('layouts.pilketos')] class extends Component {
    use WithPagination;
    public $periodes; public ?int $periodeId=null; public string $kategori='L'; public ?int $ketuaNis=null; public ?int $wakilNis=null; public int $nomorUrut=1; public string $visi=''; public string $misi=''; public string $fotoPasangan=''; public array $students=[];
    public function mount(PilketosStudentDirectory $directory): void { $this->periodes=PilketosPeriode::query()->latest('tahun')->get();$this->periodeId=$this->periodes->first()?->id;$this->loadStudents($directory); }
    public function updatedKategori(PilketosStudentDirectory $directory):void{$this->ketuaNis=$this->wakilNis=null;$this->loadStudents($directory);}
    public function updatedPeriodeId(PilketosStudentDirectory $directory):void{$this->ketuaNis=$this->wakilNis=null;$this->resetPage();$this->loadStudents($directory);}
    public function loadStudents(PilketosStudentDirectory $directory):void{$p=PilketosPeriode::query()->find($this->periodeId);$this->students=$p?$directory->eligibleStudents($p->tahun,$this->kategori):[];}
    public function save(PilketosCandidateService $service, PilketosPhotoUploadService $photos):void{$data=$this->validate(['periodeId'=>['required','exists:pilketos_periodes,id'],'kategori'=>['required','in:L,P'],'nomorUrut'=>['required','integer','min:1'],'ketuaNis'=>['required','integer','different:wakilNis'],'wakilNis'=>['required','integer'],'visi'=>['nullable','string'],'misi'=>['nullable','string'],'fotoPasangan'=>['nullable','string']]);$intent=$data['fotoPasangan']?$photos->verifyFor(auth()->user(),$data['fotoPasangan']):null;$service->create(['periode_id'=>$data['periodeId'],'kategori'=>$data['kategori'],'nomor_urut'=>$data['nomorUrut'],'ketua_nis'=>$data['ketuaNis'],'wakil_nis'=>$data['wakilNis'],'visi'=>$data['visi'],'misi'=>$data['misi'],'foto_pasangan'=>$data['fotoPasangan']?:null]);if($intent)$photos->consume($intent);$this->reset(['ketuaNis','wakilNis','visi','misi','fotoPasangan']);$this->dispatch('candidate-saved');}
    public function remove(int $id):void{$p=PilketosPasangan::query()->findOrFail($id);if($p->suara()->exists()){$this->addError('candidate','Pasangan yang sudah memiliki suara tidak dapat dihapus.');return;}$p->delete();}
    public function with():array{return['pasangan'=>PilketosPasangan::query()->where('periode_id',$this->periodeId)->orderBy('kategori')->orderBy('nomor_urut')->paginate(25)];}
}; ?>
<div><a wire:navigate href="{{route('guru.dashboard')}}" class="font-bold text-emerald-700">← Dashboard</a><h1 class="mt-4 text-3xl font-black">Pasangan kandidat</h1><form wire:submit="save" class="mt-6 grid gap-3 rounded-2xl bg-white p-5 shadow md:grid-cols-2"><select wire:model.live="periodeId" class="rounded border-slate-300">@foreach($periodes as $p)<option value="{{$p->id}}">{{$p->tahun}}</option>@endforeach</select><select wire:model.live="kategori" class="rounded border-slate-300"><option value="L">Laki-laki</option><option value="P">Perempuan</option></select><input wire:model="nomorUrut" type="number" min="1" class="rounded border-slate-300"><select wire:model="ketuaNis" class="rounded border-slate-300"><option value="">Ketua</option>@foreach($students as $s)<option value="{{$s['nis']}}">{{$s['name']}} — {{$s['nis']}} — {{$s['kelas']}}</option>@endforeach</select><select wire:model="wakilNis" class="rounded border-slate-300"><option value="">Wakil</option>@foreach($students as $s)<option value="{{$s['nis']}}" @disabled($ketuaNis===$s['nis'])>{{$s['name']}} — {{$s['nis']}} — {{$s['kelas']}}</option>@endforeach</select><textarea wire:model="visi" placeholder="Visi" class="rounded border-slate-300"></textarea><textarea wire:model="misi" placeholder="Misi" class="rounded border-slate-300"></textarea><input wire:model="fotoPasangan" placeholder="Object key foto S3" class="rounded border-slate-300"><button wire:loading.attr="disabled" class="rounded bg-emerald-700 px-4 py-2 font-bold text-white md:col-span-2">Simpan kandidat</button></form><x-input-error :messages="$errors->all()" class="mt-3"/><section class="mt-6 overflow-x-auto rounded bg-white shadow"><table class="w-full"><thead><tr><th class="p-3">No</th><th>Ketua</th><th>Wakil</th><th>Aksi</th></tr></thead><tbody>@forelse($pasangan as $p)<tr wire:key="candidate-{{$p->id}}" class="border-t"><td class="p-3">{{$p->nomor_urut}}</td><td>{{$p->ketua_nis}}</td><td>{{$p->wakil_nis}}</td><td><button wire:click="remove({{$p->id}})" class="font-bold text-red-700">Hapus</button></td></tr>@empty<tr><td colspan="4" class="p-3">Belum ada kandidat.</td></tr>@endforelse</tbody></table></section><div class="mt-4">{{$pasangan->links()}}</div></div>
